#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string a,b;cin>>a>>b;
int n=a.size(),m=b.size();
vector<int>prev(m+1,0),cur(m+1,0);int best=0;
for(int i=1;i<=n;++i){
fill(cur.begin(),cur.end(),0);
for(int j=1;j<=m;++j)if(a[i-1]==b[j-1]){
cur[j]=prev[j-1]+1;best=max(best,cur[j]);}
prev=cur;}
printf("%d\n",best);return 0;}

